$('axisunit').onchange=()=>{axesKey='';dirty=true;};$('targets').onchange=()=>{try{localStorage.setItem('scopeReference_targets',String($('targets').checked));}catch{}referenceKey='';dirty=true;};$('start').onclick=()=>{if(streaming)stop();else start();};$('inputsource').onchange=()=>{clearROI();$('fixture').disabled=$('inputsource').value==='resolve';if(streaming)start();};$('fixture').onchange=()=>{clearROI();if(streaming)start();};function selectView(settings){if(socket?.readyState===1)socket.send(JSON.stringify({type:'scope_visibility',visible:document.visibilityState==='visible'}));$('panel').hidden=!settings;$('scopeview').hidden=settings;for(const [id,selected]of [['settings',settings],['scopestab',!settings]]){$(id).setAttribute('aria-selected',String(selected));$(id).tabIndex=selected?0:-1;}dirty=true;} $('settings').onclick=()=>selectView(true);$('scopestab').onclick=()=>selectView(false);for(const id of ['settings','scopestab'])$(id).onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const settings=e.key==='End'||(e.key!=='Home'&&id==='scopestab');selectView(settings);$(settings?'settings':'scopestab').focus();}};for(const id of ['isolation','hueCenter','hueWidth','satMin','satMax','lumaMin','lumaMax','cuberesolution','precision','levelmin','levelmax','vectorzoom','sourceformat','matrix','codebits','lowcut','highcut'])$(id).onchange=e=>{if(id==='isolation')updateIsolationControls();if(e.isTrusted&&id==='isolation'&&$('isolation').value==='skin'){for(const [key,v] of Object.entries({hueCenter:25,hueWidth:20,satMin:.1,satMax:1,lumaMin:0,lumaMax:1}))$(key).value=v;}if(id==='vectorzoom')syncMagnification();if(streaming)start();};document.querySelectorAll('[data-range]').forEach(b=>b.onclick=()=>{const [min,max]=b.dataset.range.split(',');$('levelmin').value=min;$('levelmax').value=max;if(streaming)start();});
const viewTabs=document.querySelector('.view-tabs');
function placeViewTabs(){$('fullscreencontrols').prepend($('start'));viewTabs.append($('scopestab'),$('settings'));$('fullscreencontrols').before(viewTabs);viewTabs.setAttribute('aria-owns','scopestab settings');}

placeViewTabs();
$('fullscreen').onclick=async()=>{void keepAwake.set(true);selectView(false);if(!streaming){listenWhenConnected=socket?.readyState===0;start();}try{await document.documentElement.requestFullscreen();document.body.classList.add('monitor');placeViewTabs(true);dirty=true;}catch{$('signalstate').textContent='Fullscreen unavailable in this browser';}};document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement){document.body.classList.remove('monitor');placeViewTabs(false);dirty=true;}});window.addEventListener('resize',()=>{dirty=true;});const qa=new URLSearchParams(location.search);if(qa.has('visual')&&!qa.has('inputsource'))$('inputsource').value='synthetic';if(qa.has('visual'))for(const id of ['inputsource','fixture','cuberesolution','precision','levelmin','levelmax','vectorzoom','sourceformat','matrix','codebits','axisunit','x0','x1','y0','y1','lowcut','highcut','isolation','hueCenter','hueWidth','satMin','satMax','lumaMin','lumaMax'])if(qa.has(id))$(id).value=qa.get(id);if(qa.has('visual'))$('targets').checked=qa.get('targets')==='1';$('fixture').disabled=$('inputsource').value==='resolve';syncMagnification();connect();

// QA export composites the actual browser-rendered SVG overlay onto the actual
// WebGL canvas. PNG retains framebuffer pixels without JPEG quantization.
async function exportLosslessOverlays(){
 await Promise.all(canvases.map(async(canvas,i)=>{
 if(canvas.closest('section').hidden)return;
 const output=document.createElement('canvas');output.width=canvas.width;output.height=canvas.height;
 const ctx=output.getContext('2d');ctx.drawImage(canvas,0,0);
 const svg=canvas.parentElement.querySelector('svg');
 if(svg&&svg.childNodes.length){const clone=svg.cloneNode(true);clone.setAttribute('xmlns','http://www.w3.org/2000/svg');clone.setAttribute('width',canvas.width);clone.setAttribute('height',canvas.height);clone.removeAttribute('style');const img=new Image();img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(new XMLSerializer().serializeToString(clone));await img.decode();ctx.drawImage(img,0,0,canvas.width,canvas.height);}
 let link=canvas.closest('section').querySelector('.qa-overlay');if(!link){link=document.createElement('a');link.className='qa-overlay';link.textContent='Lossless overlay PNG';link.style.cssText='position:absolute;left:4px;bottom:3px;font:8px monospace;color:#aaa';canvas.closest('section').append(link);}link.href=output.toDataURL('image/png');link.download='scope-overlay-'+i+'.png';
 }));
}

if(qaLayout.has('visual')&&qaLayout.has('contexttest')){for(const [id,label,action]of [['losegpu','Test GPU loss','loseContext'],['restoregpu','Test GPU restore','restoreContext']]){const button=document.createElement('button');button.id=id;button.textContent=label;button.onclick=()=>gpuRecovery?.[action]();document.querySelector('.toolbar').append(button);}}

if(!qaLayout.has('visual'))viewerSettings=bindSettingsFiles({getLayout:()=>[...layout],setLayout:value=>{layout=value;saveLayout();applyLayout();}});

document.addEventListener('visibilitychange',()=>{if(socket?.readyState===1)socket.send(JSON.stringify({type:'scope_visibility',visible:document.visibilityState==='visible'}));});

if(!qaLayout.has('visual')||qaLayout.has('layoutpreview'))bindControlDock();

window.addEventListener('pagehide',()=>void keepAwake.set(false));document.addEventListener('click',()=>{if(streaming)void keepAwake.retry();});
